import React, { useState } from "react";
import { useNavigate } from "react-router-dom"; // para navegación
import './Administrativas.css';

export default function Administrativas() {
  const navigate = useNavigate();

  const [messages, setMessages] = useState([
    { type: "bot", content: "options", timestamp: new Date() },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMoreOptions, setShowMoreOptions] = useState(false);

  const predefinedOptions = [
    { icon: "🎓", text: "Kardex" },
    { icon: "📄", text: "Constancia" },
    { icon: "🎓", text: "Titulacion" },
    { icon: "📚", text: "Creditos" },
    { icon: "➕", text: "Mas opciones..." },
  ];

  const additionalOptions = [
    { icon: "📋", text: "Historial Academico" },
    { icon: "💳", text: "Pagos y Finanzas" },
    { icon: "📅", text: "Horarios" },
  ];

  const handleOptionClick = (option) => {
    if (option === "Mas opciones...") {
      setShowMoreOptions(true);
      setMessages([
        ...messages,
        { type: "user", content: option, timestamp: new Date() },
        { type: "bot", content: "moreOptions", timestamp: new Date() },
      ]);
    } else {
      setMessages([...messages, { type: "user", content: option, timestamp: new Date() }]);
    }
  };

  const handleSendMessage = () => {
    if (inputValue.trim()) {
      setMessages([...messages, { type: "user", content: inputValue, timestamp: new Date() }]);
      setInputValue("");
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  return (
    <div className="administrativas-container">
      {/* Header */}
      <header className="administrativas-header">
        <button className="logo-button" onClick={() => navigate("/")}>TalkinPon</button>
        <h1>Administrativas</h1>
        <div className="header-logo">
          <img
            src="/university-college-logo-circular-emblem.jpg"
            alt="Logo"
          />
        </div>
      </header>

      {/* Chat Area */}
      <div className="chat-area">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`chat-message ${message.type === "user" ? "user" : "bot"}`}
          >
            <div className="avatar">
              <img
                src="/university-college-logo-circular-emblem.jpg"
                alt={message.type === "bot" ? "Bot" : "User"}
              />
            </div>

            {message.content === "options" ? (
              <div className="options-box">
                <h3>Elige una opcion.</h3>
                {predefinedOptions.map((option, idx) => (
                  <button key={idx} onClick={() => handleOptionClick(option.text)}>
                    <span className="icon">{option.icon}</span>
                    <span>{option.text}</span>
                  </button>
                ))}
              </div>
            ) : message.content === "moreOptions" ? (
              <div className="options-box">
                <h3>Mas opciones disponibles:</h3>
                {additionalOptions.map((option, idx) => (
                  <button key={idx} onClick={() => handleOptionClick(option.text)}>
                    <span className="icon">{option.icon}</span>
                    <span>{option.text}</span>
                  </button>
                ))}
              </div>
            ) : (
              <div className={`message-box ${message.type}`}>
                <p>{message.content}</p>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Input Area */}
      <div className="input-area">
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder="Pregunta lo que quieres...."
        />
        <button onClick={handleSendMessage} className="send-button">Enviar</button>
      </div>
    </div>
  );
}
